const crypto = require('crypto');

const secret = $env.N8N_HMAC_SECRET;
if (!secret) {
  return [{ json: { valid: false, reason: 'N8N_HMAC_SECRET is not configured' } }];
}

const item = $input.first();
const rawHeaders = item.json.headers || {};
const headers = Object.fromEntries(
  Object.entries(rawHeaders).map(([k, v]) => [k.toLowerCase(), String(v)])
);

const timestamp = headers['x-lendloop-timestamp'];
const incomingSig = (headers['x-lendloop-signature'] || '').replace(/^sha256=/i, '').trim().toLowerCase();

if (!timestamp || !incomingSig) {
  return [{ json: { valid: false, reason: 'Missing HMAC timestamp or signature header' } }];
}

const tsNum = Number(timestamp);
const nowSec = Math.floor(Date.now() / 1000);
if (!Number.isFinite(tsNum) || Math.abs(nowSec - tsNum) > 300) {
  return [{ json: { valid: false, reason: 'Timestamp outside allowed 5-minute replay window' } }];
}

let rawBody;
if (item.binary && item.binary.data) {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  rawBody = buf.toString('utf8');
} else {
  rawBody = typeof item.json.body === 'string' ? item.json.body : JSON.stringify(item.json.body || {});
}

const expected = crypto
  .createHmac('sha256', secret)
  .update(`${timestamp}.${rawBody}`)
  .digest('hex');

let sigMatches = false;
try {
  sigMatches = crypto.timingSafeEqual(Buffer.from(expected, 'utf8'), Buffer.from(incomingSig, 'utf8'));
} catch {
  sigMatches = false;
}

if (!sigMatches) {
  return [{ json: { valid: false, reason: 'Invalid HMAC signature' } }];
}

const data = JSON.parse(rawBody);

const templates = {
  request_created: {
    subject: `New borrow request for ${data.toolName}`,
    message: `Hi ${data.recipientName}, ${data.actorName} requested to borrow "${data.toolName}" from ${data.startDate} to ${data.endDate}.`,
  },
  request_approved: {
    subject: `Approved: ${data.toolName}`,
    message: `Hi ${data.recipientName}, ${data.actorName} approved your request to borrow "${data.toolName}" (${data.startDate} to ${data.endDate}).`,
  },
  request_declined: {
    subject: `Declined: ${data.toolName}`,
    message: `Hi ${data.recipientName}, ${data.actorName} declined your request for "${data.toolName}".`,
  },
  loan_returned: {
    subject: `Returned: ${data.toolName}`,
    message: `Hi ${data.recipientName}, ${data.actorName} marked "${data.toolName}" as returned. Thanks for sharing!`,
  },
};

const tpl = templates[data.eventType] || {
  subject: `LendLoop update: ${data.toolName}`,
  message: `Loan update (${data.eventType}) for ${data.toolName}.`,
};

// Data minimization: pass forward only fields required to send the notification
return [{
  json: {
    valid: true,
    idempotencyKey: data.idempotencyKey,
    eventType: data.eventType,
    loanId: data.loanId,
    recipientName: data.recipientName,
    recipientEmail: data.recipientEmail,
    subject: tpl.subject,
    message: tpl.message,
  },
}];

const n = $input.first().json;
const record = {
  channel: 'mock-email',
  to: n.recipientEmail || '(no email)',
  recipientName: n.recipientName,
  subject: n.subject,
  message: n.message,
  eventType: n.eventType,
  idempotencyKey: n.idempotencyKey,
  sentAt: new Date().toISOString(),
};

console.log('[LendLoop Notification]', JSON.stringify(record));

// Swap or follow this node with an Email / Slack / Discord node using n8n Credentials.
return [{ json: { ok: true, delivered: true, idempotencyKey: n.idempotencyKey } }];
